import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    by_x = [[] for _ in range(n)]
    idx = 2
    for _ in range(m):
        l, r, x = data[idx] - 1, data[idx + 1] - 1, data[idx + 2] - 1
        idx += 3
        by_x[x].append((l, r))

    # For each x and right endpoint b, store the largest left endpoint
    # of a condition designated at x whose interval ends at or before b.
    max_left = [[-1] * n for _ in range(n)]
    for x in range(n):
        at_right = [-1] * n
        for l, r in by_x[x]:
            if l > at_right[r]:
                at_right[r] = l
        best = -1
        for b in range(n):
            if at_right[b] > best:
                best = at_right[b]
            max_left[x][b] = best

    # Binomial coefficients for interleaving the left and right subarrays.
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    # dp[a][b]: valid relative orders on positions [a,b].
    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for a in range(n - length + 1):
            b = a + length - 1
            total = 0
            for p in range(a, b + 1):
                # If a condition [l,r] with X=p is wholly inside this
                # segment, p cannot be its maximum.
                if max_left[p][b] >= a:
                    continue
                left_size = p - a
                ways = 1
                if left_size:
                    ways = dp[a][p - 1]
                if p < b:
                    ways = ways * dp[p + 1][b] % MOD
                total = (total + comb[length - 1][left_size] * ways) % MOD
            dp[a][b] = total

    print(dp[0][n - 1])

if __name__ == '__main__':
    main()

