import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    factors = []
    all_primes = set()
    for x in a:
        q = x
        d = {}
        p = 2
        while p * p <= q:
            if q % p == 0:
                e = 0
                while q % p == 0:
                    q //= p
                    e += 1
                d[p] = e
                all_primes.add(p)
            p += 1
        if q > 1:
            d[q] = 1
            all_primes.add(q)
        factors.append(d)

    answer = 1
    for prime in all_primes:
        occurrences = [(i + 1, f[prime]) for i, f in enumerate(factors) if prime in f]
        # dp[r] sums weights of paths whose current exponent is r above its minimum.
        # The accumulated weight accounts for all vertices seen so far.
        dp = {0: 1}
        current_vertex = 1
        for edge, exponent in occurrences:
            # Edges without this prime leave the exponent unchanged.
            gap = edge - current_vertex
            if gap:
                dp = {r: value * pow(prime, r * gap, MOD) % MOD
                      for r, value in dp.items()}
                current_vertex = edge

            next_dp = {}
            for r, value in dp.items():
                for delta in (exponent, -exponent):
                    nr = r - delta
                    if nr < 0:
                        # The new minimum is lower by -nr; shift all old vertices.
                        shift = -nr
                        contribution = value * pow(prime, shift * edge, MOD) % MOD
                        nr = 0
                    else:
                        contribution = value * pow(prime, nr, MOD) % MOD
                    next_dp[nr] = (next_dp.get(nr, 0) + contribution) % MOD
            dp = next_dp
            current_vertex = edge + 1

        remaining = n - current_vertex
        if remaining:
            dp = {r: value * pow(prime, r * remaining, MOD) % MOD
                  for r, value in dp.items()}
        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

