import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        groups=[[] for _ in range(n+1)]
        for idx,(a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            groups[b].append((a,idx))
        heap=[]
        gains=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,idx in groups[r]:
                heapq.heappush(heap,(-a,idx))
            if not heap:
                base+=r
                continue
            top_a=-heap[0][0]
            base+=r-top_a
            if len(heap)>=2:
                # Since heap entries are distinct pairs, second item gives second-largest a.
                second_a=-heap[1][0]
            else:
                second_a=0
            if top_a>second_a:
                gains[heap[0][1]]+=top_a-second_a
        return base+max(gains)

