import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = [None]
    for _ in range(m):
        edges.append((next(it) - 1, next(it) - 1, next(it)))

    queries = []
    closed = [False] * (m + 1)
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            e = next(it)
            queries.append((1, e))
            closed[e] = True
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e in range(1, m + 1):
        if not closed[e]:
            a, b, w = edges[e]
            dist[a][b] = dist[b][a] = w

    # Initial all-pairs shortest paths after all closures have been applied.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            answers.append(-1 if dist[x][y] == inf else dist[x][y])
        else:
            _, e = query
            u, v, w = edges[e]
            # Distances before inserting this edge; a shortest path uses it at most once.
            row_u = dist[u][:]
            row_v = dist[v][:]
            col_u = [dist[i][u] for i in range(n)]
            col_v = [dist[i][v] for i in range(n)]
            for i in range(n):
                row_i = dist[i]
                iu = col_u[i]
                iv = col_v[i]
                for j in range(n):
                    via_uv = iu + w + row_v[j]
                    via_vu = iv + w + row_u[j]
                    if via_uv < row_i[j]:
                        row_i[j] = via_uv
                    if via_vu < row_i[j]:
                        row_i[j] = via_vu

    answers.reverse()
    sys.stdout.write("\n".join(map(str, answers)))

