class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # Count smaller numbers according to their number of set bits.
        counts = [0] * (n + 1)
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # First position where the candidate is smaller: choose 0 here.
                for r in range(remaining + 1):
                    counts[prefix_ones + r] = (
                        counts[prefix_ones + r] + comb[remaining][r]
                    ) % MOD
                prefix_ones += 1

        # steps[x] is the number of popcount operations needed to reach 1.
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = steps[x.bit_count()] + 1

        answer = 0
        for ones in range(1, n + 1):
            # A number with 'ones' set bits first becomes 'ones' after one operation.
            if steps[ones] + 1 <= k:
                answer = (answer + counts[ones]) % MOD
        return answer

