import sys, heapq

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    g = [x.decode() for x in data[1:1+n]]
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    d = [[10**9] * n for _ in range(n)]
    pq = []
    finite = 0
    maxdist = 0
    for i in range(n):
        d[i][i] = 0
        finite += 1
        heapq.heappush(pq, (0, i, i))
    for u, row in enumerate(g):
        for v, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[u][c].append(v)
                incoming[v][c].append(u)
                if d[u][v] > 1:
                    d[u][v] = 1
                    finite += 1
                    maxdist = 1
                    heapq.heappush(pq, (1, u, v))
    while pq:
        w, a, b = heapq.heappop(pq)
        if d[a][b] != w:
            continue
        if finite == n*n and maxdist <= w + 2:
            break
        nd = w + 2
        for c in range(26):
            left = incoming[a][c]
            right = outgoing[b][c]
            for x in left:
                dx = d[x]
                for y in right:
                    if dx[y] > nd:
                        if dx[y] == 10**9:
                            finite += 1
                        dx[y] = nd
                        maxdist = max(maxdist, nd)
                        heapq.heappush(pq, (nd, x, y))
    print('\n'.join(' '.join(str(x if x < 10**9 else -1) for x in row) for row in d))

solve()

