import sys

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        sys.setrecursionlimit(10000)
        n, m = len(grid), len(grid[0])
        # Clockwise order in matrix coordinates: SE, SW, NW, NE.
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        @lru_cache(None)
        def extend(r: int, c: int, d: int, can_turn: bool) -> int:
            """Longest valid continuation beginning at this 0/2 cell."""
            value = grid[r][c]
            best = 1
            nr, nc = r + dirs[d][0], c + dirs[d][1]
            expected = 2 - value
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == expected:
                best = max(best, 1 + extend(nr, nc, d, can_turn))

            if can_turn:
                nd = (d + 1) % 4
                nr, nc = r + dirs[nd][0], c + dirs[nd][1]
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == expected:
                    best = max(best, 1 + extend(nr, nc, nd, False))
            return best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        answer = max(answer, 1 + extend(nr, nc, d, True))
        return answer

