from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        remaining = set(range(1, n + 1))
        answer = []
        required_parity = None  # 1 for odd, 0 for even

        for _ in range(n):
            chosen = None
            for x in sorted(remaining):
                if required_parity is not None and x % 2 != required_parity:
                    continue

                odds = sum(y % 2 for y in remaining if y != x)
                evens = len(remaining) - 1 - odds
                length = len(remaining) - 1
                next_parity = 1 - (x % 2)

                if length % 2 == 0:
                    feasible = odds == evens
                elif next_parity == 1:
                    feasible = odds == evens + 1
                else:
                    feasible = evens == odds + 1

                count = factorial(odds) * factorial(evens) if feasible else 0
                if k > count:
                    k -= count
                else:
                    chosen = x
                    break

            if chosen is None:
                return []
            answer.append(chosen)
            remaining.remove(chosen)
            required_parity = 1 - (chosen % 2)

        return answer

