class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2

        # Each left-half digit contributes to its own position and its mirror.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        coeff = [
            (powers[i] + (powers[n - 1 - i] if i != n - 1 - i else 0)) % k
            for i in range(h)
        ]

        # suffix[i] is a bitmask of possible modulo-k sums from positions i onward.
        full_mask = (1 << k) - 1
        suffix = [0] * (h + 1)
        suffix[h] = 1  # Only residue 0 is possible with no positions remaining.
        for i in range(h - 1, -1, -1):
            mask = 0
            c = coeff[i]
            for digit in range(10):
                shift = digit * c % k
                reachable = suffix[i + 1]
                if shift:
                    reachable = ((reachable << shift) | (reachable >> (k - shift))) & full_mask
                mask |= reachable
            suffix[i] = mask

        # Greedily maximize each digit, ensuring the remaining positions can
        # complete a sum congruent to zero.
        digits = []
        remainder = 0
        for i, c in enumerate(coeff):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                needed = (-(remainder + digit * c)) % k
                if (suffix[i + 1] >> needed) & 1:
                    digits.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        half = ''.join(digits)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

