from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        # next strictly greater element: boundaries of constant prefix maxima
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        dest = [nxt]
        # Cost of raising the block [i, nxt[i]) to nums[i].
        costs = [[nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
                  for i in range(n)]]
        for _ in range(1, levels):
            prev_dest = dest[-1]
            prev_cost = costs[-1]
            cur_dest = [n] * n
            cur_cost = [0] * n
            for i in range(n):
                mid = prev_dest[i]
                if mid < n:
                    cur_dest[i] = prev_dest[mid]
                    cur_cost[i] = prev_cost[i] + prev_cost[mid]
                else:
                    cur_cost[i] = prev_cost[i]
            dest.append(cur_dest)
            costs.append(cur_cost)

        def cost_to(l: int, r: int) -> int:
            pos = l
            total = 0
            for b in range(levels - 1, -1, -1):
                q = dest[b][pos]
                if q <= r:
                    total += costs[b][pos]
                    pos = q
            # Remaining part of the prefix-maximum block containing r.
            return total + nums[pos] * (r - pos + 1) - (pref[r + 1] - pref[pos])

        answer = 0
        for l in range(n):
            lo, hi = l, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost_to(l, mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            answer += lo - l + 1
        return answer

