from functools import cmp_to_key
import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # If i is outer to j, then i(f_j(x)) - j(f_i(x)) is
    # (A_i - 1) B_j - (A_j - 1) B_i. Thus larger ratios
    # (A - 1) / B should occur farther outward.
    def compare(x, y):
        d = (x[0] - 1) * y[1] - (y[0] - 1) * x[1]
        return (d > 0) - (d < 0)

    funcs.sort(key=cmp_to_key(compare))

    # Process functions from inner to outer; descending updates ensure
    # that each function is selected at most once.
    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for count in range(k, 0, -1):
            if dp[count - 1] is not None:
                value = a * dp[count - 1] + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value

    print(dp[k])

if __name__ == '__main__':
    main()

