import sys

class Fenwick:
    def __init__(self, n):
        self.n=n
        self.c=[0]*(n+1)
        self.s=[0]*(n+1)
    def add(self,i,dc,ds):
        i+=1
        while i<=self.n:
            self.c[i]+=dc; self.s[i]+=ds; i+=i&-i
    def pref(self,i):
        # first i compressed coordinates
        c=s=0
        while i:
            c+=self.c[i]; s+=self.s[i]; i-=i&-i
        return c,s
    def kth_sum(self,k):
        # sum of k smallest items (k guaranteed in range)
        if k<=0:return 0
        idx=0; cnt=sm=0; bit=1<<(self.n.bit_length()-1)
        while bit:
            ni=idx+bit
            if ni<=self.n and cnt+self.c[ni]<k:
                idx=ni; cnt+=self.c[ni]; sm+=self.s[ni]
            bit>>=1
        # idx is number of coordinates fully skipped; next coordinate has remaining needed
        return sm+(k-cnt)*vals[idx]
    def halfdiff(self,total):
        k=total//2
        if k==0:return 0
        bottom=self.kth_sum(k)
        allsum=self.pref(self.n)[1]
        return allsum-2*bottom

