import sys
MOD=998244353

def solve():
    it = iter(sys.stdin.buffer.read().decode().split())
    T = int(next(it))
    out = []
    for _ in range(T):
        H = int(next(it)); W = int(next(it))
        g = [next(it) for _ in range(H)]
        if any(s.count('A') % 2 for s in g):
            out.append('0')
            continue

        parent = list(range(H))
        xr = [0] * H

        def find(x):
            if parent[x] != x:
                old = parent[x]
                parent[x] = find(old)
                xr[x] ^= xr[old]
            return parent[x]

        ok = True
        extra = 0
        for j in range(W):
            b_rows = []
            pref = []
            parity = 0
            for i in range(H):
                pref.append(parity)
                if g[i][j] == 'B':
                    b_rows.append(i)
                else:
                    parity ^= 1

            if not b_rows:
                if parity:
                    ok = False
                else:
                    extra += 1
                continue

            for z, i in enumerate(b_rows):
                k = b_rows[(z + 1) % len(b_rows)]
                toggle = 0
                r = i
                while r != k:
                    if g[r][j] == 'A':
                        toggle ^= 1
                    r = (r + 1) % H

                # q_i xor q_k = pref_i xor pref_k xor vertical toggles
                value = pref[i] ^ pref[k] ^ toggle
                ri = find(i)
                rk = find(k)
                xi = xr[i]
                xk = xr[k]
                if ri == rk:
                    if xi ^ xk != value:
                        ok = False
                else:
                    parent[ri] = rk
                    xr[ri] = xi ^ xk ^ value

        if not ok:
            out.append('0')
            continue
        components = sum(find(i) == i for i in range(H))
        out.append(str(pow(2, components + extra, MOD)))

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

