from bisect import bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        x = p.index('*')
        y = p.index('*', x + 1)
        A, B, C = p[:x], p[x + 1:y], p[y + 1:]
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            pi = [0] * len(t)
            j = 0
            for i in range(1, len(t)):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == len(t):
                    result.append(i - len(t) + 1)
                    j = pi[j - 1]
            return result

        a_occ = occurrences(A)
        b_occ = occurrences(B)
        c_occ = occurrences(C)

        best_length = n + 1
        best_start = -1
        bi = 0
        for c in c_occ:
            # Add all B occurrences that finish no later than this C occurrence.
            while bi < len(b_occ) and b_occ[bi] + len(B) <= c:
                b = b_occ[bi]
                bi += 1
                # Latest A occurrence that finishes no later than this B.
                k = bisect_right(a_occ, b - len(A)) - 1
                if k >= 0:
                    best_start = max(best_start, a_occ[k])
            if best_start >= 0:
                best_length = min(best_length, c + len(C) - best_start)

        return best_length if best_length <= n else -1

