import sys

def solve(a, b):
    n = len(a)
    A = [i for i, c in enumerate(a) if c == '1']
    B = [i for i, c in enumerate(b) if c == '1']
    if len(A) < len(B) or B[0] < A[0] or B[-1] > A[-1]:
        return -1

    def feasible(d):
        # Each initial particle must be able to end at a target, and every
        # target must receive at least one particle. Matching all targets to
        # distinct initial particles handles the latter condition.
        j = 0
        for x in A:
            while j < len(B) and B[j] < x - d:
                j += 1
            if j == len(B) or B[j] > x + d:
                return False
        i = 0
        for y in B:
            while i < len(A) and A[i] < y - d:
                i += 1
            if i == len(A) or A[i] > y + d:
                return False
            i += 1
        return True

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

