from typing import List
class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n=len(parent)
        ch=[[] for _ in range(n)]
        for i in range(1,n): ch[parent[i]].append(i)
        start=[0]*n; end=[0]*n; t=[]
        stack=[(0,0)]
        while stack:
            u, done=stack.pop()
            if not done:
                start[u]=len(t)
                stack.append((u,1))
                for v in reversed(ch[u]): stack.append((v,0))
            else:
                t.append(s[u]); end[u]=len(t)
        m=len(t)
        odd=[0]*m; l=0; r=-1
        for i in range(m):
            k=1 if i>r else min(odd[l+r-i],r-i+1)
            while i-k>=0 and i+k<m and t[i-k]==t[i+k]: k+=1
            odd[i]=k
            if i+k-1>r: l=i-k+1; r=i+k-1
        even=[0]*m; l=0; r=-1
        for i in range(m):
            k=0 if i>r else min(even[l+r-i+1],r-i+1)
            while i-k-1>=0 and i+k<m and t[i-k-1]==t[i+k]: k+=1
            even[i]=k
            if i+k-1>r: l=i-k; r=i+k-1
        ans=[]
        for i in range(n):
            length=end[i]-start[i]
            if length%2: ans.append(odd[(start[i]+end[i]-1)//2] >= length//2+1)
            else: ans.append(even[(start[i]+end[i])//2] >= length//2)
        return ans

