class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix sums at indices with the same remainder modulo k
        # delimit subarrays whose lengths are divisible by k.
        min_prefix = [None] * k
        min_prefix[0] = 0

        prefix = 0
        answer = None
        for i, value in enumerate(nums, 1):
            prefix += value
            remainder = i % k

            if min_prefix[remainder] is not None:
                candidate = prefix - min_prefix[remainder]
                if answer is None or candidate > answer:
                    answer = candidate

            if min_prefix[remainder] is None or prefix < min_prefix[remainder]:
                min_prefix[remainder] = prefix

        return answer

