class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        # dp[c] gives the length produced by one character c after the
        # current number of transformations.
        dp = [1] * 26
        for _ in range(t):
            nxt = [0] * 26
            for c in range(25):
                nxt[c] = dp[c + 1]
            nxt[25] = (dp[0] + dp[1]) % mod
            dp = nxt
        return sum(dp[ord(ch) - ord('a')] for ch in s) % mod

