class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s in dp[i] means index i can be decremented by a total of s.
        dp = [1] * n
        masks = [(1 << (x + 1)) - 1 for x in nums]

        if all(x == 0 for x in nums):
            return 0

        for qi, (left, right, val) in enumerate(queries):
            for i in range(left, right + 1):
                dp[i] = (dp[i] | (dp[i] << val)) & masks[i]
            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return qi + 1

        return -1

