import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        length = len(str(n))
        if len(str(m)) != length:
            return -1

        upper = 10 ** length
        prime = bytearray(b'\x01') * upper
        prime[0] = 0
        if upper > 1:
            prime[1] = 0
        for p in range(2, int(upper ** 0.5) + 1):
            if prime[p]:
                start = p * p
                count = (upper - 1 - start) // p + 1
                prime[start:upper:p] = b'\x00' * count

        if prime[n] or prime[m]:
            return -1

        lower = 10 ** (length - 1)
        places = [10 ** i for i in range(length)]
        dist = {n: n}  # Include the starting value in the transformation cost.
        queue = [(n, n)]

        while queue:
            cost, value = heapq.heappop(queue)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                for delta in (-1, 1):
                    if not 0 <= digit + delta <= 9:
                        continue
                    nxt = value + delta * place
                    # Keep the same digit length and never visit a prime.
                    if nxt < lower or prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < dist.get(nxt, float('inf')):
                        dist[nxt] = new_cost
                        heapq.heappush(queue, (new_cost, nxt))

        return -1

