class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        ans = 0
        old = [0] * (n + 1)
        for i in range(n - 1, 0, -1):
            for j in range(n - 1, i, -1):
                cur = old[j + 1] + 1 if nums[i] == nums[j] else 0
                old[j] = cur
                if (j >= 2 * i and z[i] >= i) or cur >= j - i:
                    ans += 1
            old[i] = 0
        return ans

