class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        targets = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        for i, c in enumerate(source):
            ndp = [neg] * (m + 1)
            removable = i in targets
            for j, val in enumerate(dp):
                if val == neg:
                    continue
                # Keep the source character without using it for pattern.
                ndp[j] = max(ndp[j], val)
                if removable:
                    ndp[j] = max(ndp[j], val + 1)
                if j < m and c == pattern[j]:
                    ndp[j + 1] = max(ndp[j + 1], val)
            dp = ndp
        return dp[m]

