from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        inf = 10**30
        # State (left color, right color) for the current symmetric pair.
        dp = [[inf] * 3 for _ in range(3)]
        for left in range(3):
            for right in range(3):
                if left != right:
                    dp[left][right] = cost[0][left] + cost[n - 1][right]

        # Move inward one symmetric pair at a time. The new pair must differ
        # from the preceding pair on both sides to avoid equal adjacent colors.
        for i in range(1, n // 2):
            ndp = [[inf] * 3 for _ in range(3)]
            for left in range(3):
                for right in range(3):
                    if left == right:
                        continue
                    pair_cost = cost[i][left] + cost[n - 1 - i][right]
                    for prev_left in range(3):
                        for prev_right in range(3):
                            if (prev_left != prev_right and prev_left != left
                                    and prev_right != right):
                                ndp[left][right] = min(
                                    ndp[left][right],
                                    dp[prev_left][prev_right] + pair_cost
                                )
            dp = ndp

        return min(min(row) for row in dp)

