from typing import List
class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        lo = max(bounds[i][0] - original[i] for i in range(len(original)))
        hi = min(bounds[i][1] - original[i] for i in range(len(original)))
        return max(0, hi - lo + 1)

if __name__ == '__main__':
    s=Solution()
    assert s.countArrays([1,2,3,4], [[1,2],[2,3],[3,4],[4,5]]) == 2
    assert s.countArrays([1,2,3,4], [[1,10],[2,9],[3,8],[4,7]]) == 4
    assert s.countArrays([1,2,1,2], [[1,1],[2,3],[3,3],[2,3]]) == 0

